function officeAllDiscussions(){const topics=new Map(officeDiscussionHistory.map(item=>[String(item.id),item]));for(const item of officeTeam().discussions||[])topics.set(String(item.id),item);return [...topics.values()].sort((a,b)=>b.id-a.id)}
const officeDiscussionStatus={open:'Đang trao đổi',resolved:'Đã chốt',informational:'Cập nhật',needs_attention:'Cần xử lý',stale:'Phạm vi trước'};
function officeDiscussionPost(post,full=false){return '<article class="office-message"><div class="office-message-meta"><strong>'+escape(officeMessageName(post.sender_agent_id))+'</strong><time>'+escape(localTime(post.created_at))+'</time></div>'+(post.mentions.length?'<p class="office-message-recipient">Gọi '+post.mentions.map(id=>escape(officeMessageName(id))).join(', ')+'</p>':'')+(post.kind==='conclusion'?'<p class="office-discussion-conclusion">Kết luận và hành động</p>':'')+'<p class="office-message-text'+(full?' full':'')+'">'+escape(post.text)+'</p>'+post.evidence.map(id=>'<a class="office-text-button" href="/?evidence='+encodeURIComponent(id)+'" data-evidence="'+escape(id)+'">Xem bằng chứng</a>').join('')+'</article>'}
function renderOfficeDiscussionFeed(selected){const topics=officeAllDiscussions().filter(item=>selected==='all'||item.owner_agent_id===selected||item.posts.some(post=>post.sender_agent_id===selected||post.mentions.includes(selected))),key=JSON.stringify(['group',selected,topics]);if(key===officeFeedKey)return;officeFeedKey=key;const panel=document.querySelector('#office-exchange'),items=document.querySelector('#office-exchange-items'),scroll=panel.scrollTop,focus=document.activeElement?.dataset.officeDiscussion;items.innerHTML=topics.map(topic=>'<article class="office-discussion-card"><div class="office-discussion-heading"><h3>'+escape(topic.title)+'</h3><span>'+escape(officeDiscussionStatus[topic.status]||'Chưa xác nhận')+'</span></div><p class="office-note">'+escape(topic.task_title)+' · Phụ trách: '+escape(officeMessageName(topic.owner_agent_id))+'</p>'+topic.posts.map(post=>officeDiscussionPost(post,true)).join('')+'<button class="office-text-button" data-office-discussion="'+topic.id+'">Xem cuộc trao đổi · '+topic.posts.length+' tin</button></article>').join('')||'<p class="office-empty">Chưa có trao đổi nhóm. Các câu hỏi, câu trả lời và kết luận thực tế sẽ xuất hiện tại đây.</p>';panel.scrollTop=scroll;if(focus)[...items.querySelectorAll('[data-office-discussion]')].find(button=>button.dataset.officeDiscussion===focus)?.focus({preventScroll:true})}
function openOfficeDiscussion(id){const topic=officeAllDiscussions().find(item=>String(item.id)===String(id));if(!topic)return;officeDiscussionOpened=id;officeMessageOpened=null;const dialog=document.querySelector('#office-message-dialog'),content=document.querySelector('#office-message-content'),scroll=dialog.scrollTop,key=JSON.stringify(topic);if(content.dataset.discussion!==key){content.dataset.discussion=key;content.innerHTML='<h3>'+escape(topic.title)+'</h3><p class="office-note">'+escape(topic.task_title)+' · '+escape(officeDiscussionStatus[topic.status]||'Chưa xác nhận')+'</p><p class="office-note">Phụ trách kết luận: '+escape(officeMessageName(topic.owner_agent_id))+'</p>'+topic.posts.map(post=>officeDiscussionPost(post,true)).join('')+(topic.requests.length?'<section class="office-discussion-requests"><h4>Thành viên được giao phản hồi</h4>'+topic.requests.map(request=>'<p>'+escape(officeMessageName(request.agent_id))+' · '+escape({queued:'Đang chờ nhận việc',running:'Đang thực hiện',completed:'Đã phản hồi',blocked:'Cần xử lý',cancelled:'Đã dừng'}[request.status]||'Chưa xác nhận')+(request.purpose==='synthesize'?' · Tổng hợp kết luận':'')+'</p>').join('')+'</section>':'');dialog.scrollTop=scroll}if(!dialog.open)dialog.showModal()}
async function loadOfficeDiscussionHistory(){const button=document.querySelector('#office-history-load'),note=document.querySelector('#office-history-status');button.disabled=true;button.textContent='Đang tải lịch sử…';try{const response=await fetch('/api/team/discussions?after='+officeDiscussionCursor+'&limit=50');if(!response.ok)throw new Error('history');const page=await response.json();officeDiscussionHistory.push(...page.items);officeDiscussionCursor=page.cursor;officeDiscussionLoaded=true;officeDiscussionMore=page.has_more;officeFeedKey=null;renderOfficeFeed();note.textContent=officeDiscussionMore?'Đã tải một phần lịch sử nhóm. Có thể tải tiếp.':'Đã tải toàn bộ chủ đề đã lưu.'}catch{note.textContent='Chưa tải được trao đổi nhóm. Bạn có thể thử lại.'}finally{button.disabled=officeDiscussionLoaded&&!officeDiscussionMore;button.textContent=officeDiscussionMore?'Tải tiếp lịch sử':'Đã tải hết lịch sử'}}

function rememberOfficeDiscussions(topics){const cache=new Map(officeDiscussionHistory.map(item=>[String(item.id),item]));for(const topic of topics)cache.set(String(topic.id),topic);officeDiscussionHistory=[...cache.values()]}
async function refreshOfficeDiscussionHistory(){if(officeDiscussionRefreshing)return;const latest=new Set((officeTeam().discussions||[]).map(item=>String(item.id))),ids=officeDiscussionHistory.filter(item=>!latest.has(String(item.id))&&(['open','needs_attention'].includes(item.status)||String(item.id)===String(officeDiscussionOpened))).map(item=>item.id);if(!ids.length)return;officeDiscussionRefreshing=true;try{for(let i=0;i<ids.length;i+=100){const response=await fetch('/api/team/discussions?ids='+ids.slice(i,i+100).join(','));if(!response.ok)throw new Error('history');const page=await response.json();rememberOfficeDiscussions(page.items)}officeFeedKey=null;renderOfficeFeed();if(officeDiscussionOpened!==null&&document.querySelector('#office-message-dialog').open)openOfficeDiscussion(officeDiscussionOpened)}catch{document.querySelector('#office-history-status').textContent='Chưa cập nhật được cuộc trao đổi cũ. Hệ thống sẽ thử lại khi có kết nối.'}finally{officeDiscussionRefreshing=false}}

function rememberOfficeMessages(messages){const cache=new Map(officeHistory.map(item=>[String(item.id),item]));for(const message of messages)cache.set(String(message.id),message);officeHistory=[...cache.values()]}
function updateOfficeMessage(){const message=officeAllMessages().find(item=>String(item.id)===String(officeMessageOpened));if(!message)return;const dialog=document.querySelector('#office-message-dialog'),content=document.querySelector('#office-message-content'),markup=officeMessageMarkup(message,true);if(content.innerHTML!==markup){const scroll=dialog.scrollTop;content.innerHTML=markup;dialog.scrollTop=scroll}}
async function refreshOfficeMessageHistory(){if(officeMessageRefreshing)return;const latest=new Set((officeTeam().messages||[]).map(item=>String(item.id))),ids=officeHistory.filter(item=>!latest.has(String(item.id))&&(!['acknowledged','cancelled'].includes(item.status)||String(item.id)===officeMessageOpened)).map(item=>item.id);if(!ids.length)return;officeMessageRefreshing=true;try{for(let i=0;i<ids.length;i+=100){const response=await fetch('/api/team/messages?ids='+ids.slice(i,i+100).join(','));if(!response.ok)throw new Error('history');const page=await response.json();rememberOfficeMessages(page.items)}officeFeedKey=null;officeInspectorKey=null;renderOfficeFeed();renderOfficeInspector();if(officeMessageOpened!==null&&document.querySelector('#office-message-dialog').open)updateOfficeMessage()}catch{document.querySelector('#office-history-status').textContent='Chưa cập nhật được tin riêng đã lưu. Hệ thống sẽ thử lại khi có kết nối.'}finally{officeMessageRefreshing=false}}

function officeLatestActivity(run){return run?(officeTeam().events||[]).filter(event=>event.run_id===run.id).at(-1):null}
function officeActivityText(run){const event=officeLatestActivity(run),data=event?.data||{},names={commandExecution:'Đang chạy công cụ',fileChange:'Đang cập nhật mã nguồn',reasoning:'Đang xử lý công việc',agentMessage:'Đang cập nhật kết quả',mcpToolCall:'Đang dùng công cụ',webSearch:'Đang tìm thông tin'};if(!run)return 'Chưa có phiên làm việc';if(event?.type==='mission.progress'){const task=state.tasks.find(task=>task.id===run.task_id),step=task?.steps.find(step=>step.id===data.step);return step?'Bước hiện tại: '+step.title:'Đang cập nhật tiến độ'}if(event?.type==='runtime.activity')return names[data.item_type]||'Đã nhận hoạt động từ phiên thực hiện';return officeStatusLabels[run.status]||'Chưa xác nhận hoạt động'}
function officeRosterWork(id){const run=officeRun(officeAgent(id)),task=state.tasks.find(task=>task.id===run?.task_id);return '<span class="office-roster-task">'+escape(task?.title||(state.config.awaiting_request?'Chờ bạn giao yêu cầu':'Chưa nhận công việc'))+'</span>'+(run?'<span class="office-roster-activity">'+escape(officeActivityText(run))+' · '+escape(localTime(run.last_activity_at||run.ended_at||run.started_at))+'</span>':'')}
function officeRosterLink(id){const run=officeRun(officeAgent(id));if(!run?.thread_id)return '';return '<a class="office-roster-link" href="codex://threads/'+encodeURIComponent(run.thread_id)+'">Mở phiên Codex</a><p class="office-session-note">Phiên chạy nền; chưa xác nhận hiển thị trong danh sách chat Codex App.</p>'}
function renderOfficeWorkSummary(){const node=document.querySelector('#office-work-summary');if(!node)return;const team=officeTeam(),fresh=officeSupervisorFresh(),runs=(team.runs||[]).filter(run=>['preparing','dispatching','running','checking','unknown','backoff'].includes(run.status)),working=fresh?runs.filter(run=>['running','checking'].includes(run.status)):[],questions=(team.company?.questions||[]).filter(q=>q.status==='open'),pending=(team.company?.capability_jobs||[]).filter(job=>['queued','claimed','bound','unknown'].includes(job.status));let title,detail;
if(!officeConnected){title='Chưa có kết nối cập nhật';detail='Đang giữ dữ liệu đã nhận; chưa xác nhận nhân viên còn làm việc.'}
else if(state.config.awaiting_request){title='Chờ bạn giao yêu cầu';detail='Công ty đã mở. Mô tả sản phẩm trong chat Codex để bắt đầu.'}
else if(!team.enabled){title=state.execution?.active?'Chat Codex đang làm việc':'Chưa có đội ngũ đang chạy';detail='Dự án này làm việc theo chat Codex; xem phiên thực hiện ở trang Tổng quan.'}
else if(!fresh){title=team.supervisor?.status==='stopped'?'Bộ điều phối đã dừng':'Chưa xác nhận công ty đang chạy';detail=runs.length?'Có phiên cần đối chiếu. Chưa thể xác nhận chỉ từ trạng thái đã lưu.':'Chưa có phiên làm việc đang được xác nhận. Mở văn phòng không tự chạy nhân viên.'}
else if(working.length){title=working.length+' nhân viên đang làm việc';detail=working.slice(0,3).map(run=>officeMessageName(run.agent_id)+' · '+(state.tasks.find(task=>task.id===run.task_id)?.title||'Đang nhận công việc')).join(' / ')}
else if(questions.length){title='Chờ bạn trả lời';detail=questions[0].question}
else if(pending.length){title='Chờ công cụ thực hiện';detail='Có yêu cầu ảnh hoặc kiểm chứng cần xử lý trong chat Codex được giao.'}
else if(runs.some(run=>run.status==='unknown')){title='Có phiên chưa rõ kết quả';detail='Điều phối đang đối chiếu; chưa khởi chạy lặp lại.'}
else if(runs.length){title='Đang chuẩn bị hoặc chờ thực hiện';detail='Xem trạng thái và công việc của từng nhân viên trong danh sách.'}
else{title='Điều phối đang chờ công việc';detail='Hiện không có nhân viên đang thực hiện; xem đầu vào, mốc duyệt và trạng thái dự án.'}
const key=JSON.stringify([title,detail]);if(key===officeWorkKey)return;officeWorkKey=key;node.innerHTML='<strong>'+escape(title)+'</strong><span>'+escape(detail)+'</span>'}

function officeOpenQuestions(){return (officeTeam().company?.questions||[]).filter(question=>question.status==='open'&&question.is_current!==false)}
function officeQuestionsFor(id){return officeOpenQuestions().filter(question=>question.source_agent_id===id||officeAgent(question.source_agent_id)?.base_role===id)}
function officeQuestionLink(question){const reply=question.owner_thread_id?'<a class="office-question-link" href="codex://threads/'+encodeURIComponent(question.owner_thread_id)+'">'+officeIcon('message-square')+'Trả lời trong chat dự án</a>':'<p class="office-note">Trả lời trong chat Codex dự án đang dùng. Chưa liên kết được nút mở chat chủ sản phẩm.</p>';return reply+(question.source_thread_id?'<a class="office-text-button" href="codex://threads/'+encodeURIComponent(question.source_thread_id)+'">Xem phiên gửi câu hỏi</a>':'')}

function renderOfficeQuestions(){const questions=officeOpenQuestions(),alert=document.querySelector('#office-owner-alert'),panel=document.querySelector('#office-owner-questions');if(!alert||!panel)return;const key=JSON.stringify([questions,officeConnected]);if(alert.dataset.questions===key)return;alert.dataset.questions=key;alert.hidden=!questions.length;alert.innerHTML=questions.length?officeIcon('message-square')+'<div><strong>'+questions.length+' câu hỏi cần bạn trả lời</strong><p>'+escape(questions[0].question)+(officeConnected?'':' · Dữ liệu đã nhận; đang kết nối lại')+'</p></div>'+officeQuestionLink(questions[0]):'';const scroll=document.querySelector('#office-exchange').scrollTop;panel.innerHTML=questions.map(question=>'<article class="office-question-action" id="office-question-'+escape(question.id)+'" tabindex="-1"><p class="office-company-state">Cần bạn trả lời · '+escape(officeMessageName(question.source_agent_id))+'</p>'+officeQuestionMarkup(question)+officeQuestionLink(question)+'</article>').join('');document.querySelector('#office-exchange').scrollTop=scroll}
function openOfficeQuestion(id){const question=officeOpenQuestions().find(question=>String(question.id)===String(id));if(!question)return;toggleOfficePanel('exchange',true);renderOfficeQuestions();const card=document.getElementById('office-question-'+question.id);card?.focus({preventScroll:true});card?.scrollIntoView({block:'nearest'});if(question.owner_thread_id)window.location.href='codex://threads/'+encodeURIComponent(question.owner_thread_id)}
